(()=>{'use strict';const C=window.CageCapabilities;
const prototypes={'Complete Unit':[65,65,65,70,65,80],'All-Out Assault':[90,30,70,45,45,35],'Iron Fortress':[30,90,40,60,90,40],'The Wall':[35,85,60,60,85,50],'Counterstrike':[55,80,45,85,80,45],'The Architects':[75,40,85,55,45,55],'Spear and Shield':[80,60,50,75,65,45],'The Engine Room':[50,75,80,65,80,75],'The Orchestra':[50,40,90,50,45,60],'Street Artists':[85,30,75,70,45,50]};
function capabilityRole(p){return C.phaseProfile(p);}
function cohesionPoints(ps){const c=ps.map(C.comp);let points=0;if(Math.max(...c.map(x=>x.DEF))>=80||C.avg(c.map(x=>x.press))>=78)points++;if(Math.max(...c.map(x=>x.pass))>=85||Math.max(...c.map(x=>x.escape))>=85||Math.max(...c.map(x=>x.dribble))>=88)points++;if(Math.max(...c.map(x=>x.shot))>=85||c.filter(x=>x.shot>=78).length>=2)points++;
const pair=test=>c.some((a,i)=>c.some((b,j)=>i!==j&&test(a,b))),pairings=[pair((a,b)=>a.pass>=88&&b.a.pace>=88),c.some(x=>x.DEF>=80)&&c.filter(x=>x.dribble>=85).length>=2,pair((a,b)=>a.a.phys>=85&&b.pass>=88),c.filter(x=>x.escape>=85).length>=2];points+=Math.min(3,pairings.filter(Boolean).length);if(c.filter(x=>x.dribble>=85&&x.a.wr<55).length>=2)points--;if(!c.some(x=>x.a.sta>=70))points--;return points;}
function describe(ps){if(ps.some(p=>p.attributesProvisional))return {visible:false};const grades=C.grades(ps),v=C.keys.map(k=>grades[k]),norm=a=>Math.sqrt(a.reduce((s,x)=>s+x*x,0));let nearest=null,best=-Infinity;for(const [label,p] of Object.entries(prototypes)){const cosine=p.reduce((s,x,i)=>s+x*v[i],0)/(norm(p)*norm(v));if(cosine>best){best=cosine;nearest=label;}}
const points=cohesionPoints(ps),cdf=window.CAGE_TACTICAL_CALIBRATION.cohesion,percentile=(cdf.filter(x=>x<points).length+.5*cdf.filter(x=>x===points).length)/cdf.length,cohesion=percentile>=.9?'S':percentile>=.65?'A':percentile>=.35?'B':percentile>=.1?'C':'D';return {visible:true,label:nearest,grades,cohesion,points,roles:ps.map(capabilityRole)};}
window.CageTacticalIdentity={describe,capabilityRole,cohesionPoints,prototypes};})();

